import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type Preset = { id: string; label: string; offsetDays: number };

const PRESETS: Preset[] = [
  { id: 'today', label: 'Сегодня', offsetDays: 0 },
  { id: 'yesterday', label: 'Вчера', offsetDays: -1 },
  { id: 'week-ago', label: 'Неделя назад', offsetDays: -7 },
];

function startOfDay(date: Date): Date {
  const next = new Date(date);
  next.setHours(0, 0, 0, 0);
  return next;
}

function shiftDays(offsetDays: number): Date {
  const next = startOfDay(new Date());
  next.setDate(next.getDate() + offsetDays);
  return next;
}

function isSameDay(a: Date | null, b: Date): boolean {
  return (
    a !== null &&
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

export interface ReportDatePickerProps {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
}

export default function ReportDatePicker({ value, defaultValue = null, onChange }: ReportDatePickerProps) {
  const [innerValue, setInnerValue] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : innerValue;

  const commit = (next: Date | null) => {
    if (value === undefined) setInnerValue(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {PRESETS.map((preset) => {
          const presetDate = shiftDays(preset.offsetDays);
          const active = isSameDay(selected, presetDate);
          return (
            <JxChip
              key={preset.id}
              active={active}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              style={{ borderRadius: 'var(--jx-r-pill)', cursor: 'pointer' }}
              onClick={() => commit(shiftDays(preset.offsetDays))}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  commit(shiftDays(preset.offsetDays));
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar
        locale="ru-RU"
        aria-label="Дата отчёта"
        value={selected}
        onValueChange={commit}
      />
    </div>
  );
}

